import { readFileSync } from 'node:fs';
import process from 'node:process';

export function rawUserArgBytes() {
  const want = process.argv.length - 2;          // count of user args per Node
  if (want <= 0) return [];
  let buf;
  try { buf = readFileSync('/proc/self/cmdline'); } catch { return null; }
  if (!buf || buf.length === 0) return null;
  const bytes = Uint8Array.from(buf);
  // split on NUL
  const entries = [];
  let start = 0;
  for (let i = 0; i < bytes.length; i++) {
    if (bytes[i] === 0) { entries.push(bytes.slice(start, i)); start = i + 1; }
  }
  if (start < bytes.length) entries.push(bytes.slice(start, bytes.length)); // no trailing NUL
  if (entries.length < want) return null;
  return entries.slice(entries.length - want);   // tail-align
}

// strict UTF-8 decode with PEP 383 surrogateescape
export function decodeSurrogateescape(bytes) {
  let out = '';
  const n = bytes.length;
  let i = 0;
  const esc = (b) => String.fromCharCode(0xDC00 + b);
  while (i < n) {
    const b0 = bytes[i];
    if (b0 < 0x80) { out += String.fromCharCode(b0); i++; continue; }
    let need = 0, lo = 0x80, hi = 0xBF, cp = 0;
    if (b0 >= 0xC2 && b0 <= 0xDF) { need = 1; cp = b0 & 0x1F; }
    else if (b0 >= 0xE0 && b0 <= 0xEF) {
      need = 2; cp = b0 & 0x0F;
      if (b0 === 0xE0) lo = 0xA0;
      if (b0 === 0xED) hi = 0x9F;
    } else if (b0 >= 0xF0 && b0 <= 0xF4) {
      need = 3; cp = b0 & 0x07;
      if (b0 === 0xF0) lo = 0x90;
      if (b0 === 0xF4) hi = 0x8F;
    } else { out += esc(b0); i++; continue; }   // 0x80-0xC1, 0xF5-0xFF
    if (i + need >= n + 0 && i + need > n - 1) { out += esc(b0); i++; continue; } // truncated
    let ok = true;
    for (let k = 1; k <= need; k++) {
      const bk = bytes[i + k];
      const min = k === 1 ? lo : 0x80, max = k === 1 ? hi : 0xBF;
      if (bk < min || bk > max) { ok = false; break; }
      cp = (cp << 6) | (bk & 0x3F);
    }
    if (!ok) { out += esc(b0); i++; continue; }
    out += String.fromCodePoint(cp);
    i += need + 1;
  }
  return out;
}

export function pyArgv() {
  const raw = rawUserArgBytes();
  if (raw === null) return process.argv.slice(2);  // fallback: lossy but best available
  return raw.map(decodeSurrogateescape);
}
EOF
