import { pyArgv } from './argvbytes.mjs';
const s = pyArgv()[0] ?? '';
const cps = [...s];
const L = cps.length;
// find first run of lone surrogates
let start = -1, end = -1;
for (let i = 0; i < L; i++) {
  const c = cps[i].codePointAt(0);
  if (c >= 0xD800 && c <= 0xDFFF) { if (start < 0) start = i; end = i; }
  else if (start >= 0) break;
}
