  let B = 0;
  for (const c of cps) { const v = c.codePointAt(0); B += v < 0x80 ? 1 : v < 0x800 ? 2 : v < 0x10000 ? 3 : 4; }
  if (B === L) console.log('OK');
  else console.log(`bytes object of wrong length, expected ${L}, found ${B}`);
}
